commit a7df7651731bcf7a3308e26050c11f648de4c7f6
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Mon May 22 10:04:46 2017 +0100

    Fix buffer overrun in vcf_format.

    Fixes #537

    Also "fixed" the parser to prevent this from happening in the first
    place, but poorly as there is no way to return an error from
    bcf_hdr_register_hrec.

    The following minimal VCF triggered this crash. Note "dype".

        ##fileformat=VCFv4.1
        ##INFO=<ID=S,Number=1,dype=String,Description="blah">
        ##INFO=<ID=I,Number=1,Type=Integer,Description="blah">
        ##contig=<ID=chr1,length=249250621,assembly=b37>
        #CHROM      POS     ID      REF     ALT     QUAL    FILTER  INFO
        chr1        10327   .       T       C       .       .       S=foo;I=12345
        chr1        10327   .       T       C       .       .       S=foo;I=12345
---
 vcf.c | 13 ++++++++++++-
 1 file changed, 12 insertions(+), 1 deletion(-)

diff --git a/vcf.c b/vcf.c
index 522627e4..b71d3305 100644
--- a/vcf.c
+++ b/vcf.c
@@ -500,6 +500,11 @@ int bcf_hdr_register_hrec(bcf_hdr_t *hdr, bcf_hrec_t *hrec)
             if (var != BCF_VL_FIXED) num = 0xfffff;
         }
     }
+    if (strcmp(hrec->key, "INFO") == 0 && type == -1) {
+        if (hts_verbose >= 2)
+            fprintf(stderr, "[E::%s] An INFO field has no Type defined. Assuming String\n", __func__);
+        type = BCF_HT_STR;
+    }
     uint32_t info = ((((uint32_t)num) & 0xfffff)<<12 |
                      (var & 0xf) << 8 |
                      (type & 0xf) << 4 |
@@ -2533,6 +2538,11 @@ int vcf_format(const bcf_hdr_t *h, const bcf1_t *v, kstring_t *s)
             if ( !z->vptr ) continue;
             if ( !first ) kputc(';', s);
             first = 0;
+            if (z->key >= h->n[BCF_DT_ID]) {
+                fprintf(stderr, "[E::%s] invalid BCF, the INFO index is too large.\n", __func__);
+                errno = EINVAL;
+                return -1;
+            }
             kputs(h->id[BCF_DT_ID][z->key].key, s);
             if (z->len <= 0) continue;
             kputc('=', s);
@@ -2612,7 +2622,8 @@ int vcf_write(htsFile *fp, const bcf_hdr_t *h, bcf1_t *v)
 {
     int ret;
     fp->line.l = 0;
-    vcf_format1(h, v, &fp->line);
+    if (vcf_format1(h, v, &fp->line) != 0)
+        return -1;
     if ( fp->format.compression!=no_compression )
         ret = bgzf_write(fp->fp.bgzf, fp->line.s, fp->line.l);
     else
commit 1acad458ca8a30f6a3a0d98b1a2e8651c3f1bd44
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Mon Apr 10 09:33:51 2017 +0100

    Fix buffer overrun on corrupted data.

    Fixes #507

    (Note this bug has nothing to do with the c->l_extranul code.  It is
    simply that b->l_data (block_len-32) is smaller than c->l_qname.)
---
 sam.c | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/sam.c b/sam.c
index 46f0b652..dca2d58f 100644
--- a/sam.c
+++ b/sam.c
@@ -414,7 +414,9 @@ int bam_read1(BGZF *fp, bam1_t *b)
     if (bgzf_read(fp, b->data, c->l_qname) != c->l_qname) return -4;
     for (i = 0; i < c->l_extranul; ++i) b->data[c->l_qname+i] = '\0';
     c->l_qname += c->l_extranul;
-    if (bgzf_read(fp, b->data + c->l_qname, b->l_data - c->l_qname) != b->l_data - c->l_qname) return -4;
+    if (b->l_data < c->l_qname ||
+        bgzf_read(fp, b->data + c->l_qname, b->l_data - c->l_qname) != b->l_data - c->l_qname)
+        return -4;
     if (fp->is_be) swap_data(c, b->l_data, b->data, 0);
     return 4 + block_len;
 }
commit b8720d00fc8ae32f867a1e5dd1d7ac78fed45459
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Wed Apr 29 12:44:55 2015 +0100

    Fixed buffer overrun in MD tag calculation.

    This occurred where the CRAM container/slice header is shorter than
    the alignments held within it.
---
 cram/cram_decode.c | 8 +++++---
 1 file changed, 5 insertions(+), 3 deletions(-)

diff --git a/cram/cram_decode.c b/cram/cram_decode.c
index 2625cf5e..21607925 100644
--- a/cram/cram_decode.c
+++ b/cram/cram_decode.c
@@ -1251,13 +1251,15 @@ static int cram_decode_seq(cram_fd *fd, cram_container *c, cram_slice *s,
                        nm--;
                    }
                } else {
-                   ref_base = fd->L1[(uc)s->ref[ref_pos - s->ref_start +1]];
+                   char ref_call = ref_pos <= s->ref_end
+                       ? (uc)s->ref[ref_pos - s->ref_start +1]
+                       : 'N';
+                   ref_base = fd->L1[ref_call];
                    seq[pos-1] = c->comp_hdr->
                        substitution_matrix[ref_base][base];
                    if (decode_md) {
                        BLOCK_APPEND_UINT(s->aux_blk, md_dist);
-                       BLOCK_APPEND_CHAR(s->aux_blk,
-                                         s->ref[ref_pos-s->ref_start +1]);
+                       BLOCK_APPEND_CHAR(s->aux_blk, ref_call);
                        md_dist = 0;
                    }
                }
